# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "Hybrid" look: Zed-style chrome (title bar, status bar, command
#          palette) around TUI-style monospace cells with rich web output.
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx

from ..sample import CELLS, MODES, PALETTE_COMMANDS
from .common import code_block, html_table, switcher


class HybridState(rx.State):
    """Only state in the mockup: whether the command palette overlay is showing."""

    palette_open: bool = False

    @rx.event
    def toggle_palette(self):
        self.palette_open = not self.palette_open


def _output(output: dict | None) -> rx.Component | None:
    if output is None:
        return None
    if output["kind"] == "table":
        return rx.el.div(html_table(output["columns"], output["rows"]), class_name="output")
    if output["kind"] == "reply":
        return rx.el.div(
            rx.el.p(output["paragraph"]),
            rx.el.ul(*[rx.el.li(b) for b in output["bullets"]]),
            class_name="output reply sans",
        )
    return rx.el.pre(output["text"], class_name="output")


def cell_view(cell: dict, output: rx.Component | None = None) -> rx.Component:
    """One hybrid-style cell; `output` replaces the default rendering of the cell's output."""
    focused = cell.get("focused", False)
    return rx.el.div(
        rx.el.div(
            rx.el.span(MODES[cell["mode"]]["icon"], class_name="prompt"),
            code_block(cell["code"], cursor=focused),
            rx.el.span(MODES[cell["mode"]]["label"], class_name="chip sans"),
            class_name="input",
        ),
        output if output is not None else _output(cell["output"]),
        class_name=f"cell m-{cell['mode']}" + (" is-focused" if focused else ""),
    )


def _palette() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.div(
                rx.el.span(">", class_name="t-cm"),
                " notebook",
                rx.el.span(" ", class_name="cursor"),
                class_name="palette-input mono",
            ),
            *[
                rx.el.div(
                    rx.el.span(name),
                    rx.el.span(key, class_name="kbd mono"),
                    class_name="palette-row" + (" is-selected" if i == 0 else ""),
                )
                for i, (name, key) in enumerate(PALETTE_COMMANDS)
            ],
            class_name="palette sans",
        ),
        class_name="palette-layer",
        on_click=HybridState.toggle_palette,
    )


def chrome(*cells: rx.Component, look: str) -> rx.Component:
    """Title bar, scrolling cell column, status bar, palette and switcher around `cells`."""
    return rx.el.div(
        rx.el.div(
            rx.el.span("reflex-kernel", class_name="title"),
            rx.el.span("~/repos/delulu-smash", class_name="dim"),
            rx.el.button(
                "Command Palette ",
                rx.el.span("Ctrl+K", class_name="kbd mono"),
                on_click=HybridState.toggle_palette,
                class_name="bar-button",
            ),
            class_name="titlebar sans",
        ),
        rx.el.div(rx.el.div(*cells, class_name="column"), class_name="hy-body mono"),
        rx.el.div(
            rx.el.span(rx.el.span(MODES["python"]["icon"], class_name="mono accent-green"), " python"),
            rx.el.span(rx.el.span("●", class_name="accent-green"), " kernel idle"),
            rx.el.span(class_name="spacer"),
            rx.el.span("Ctrl+Enter run", class_name="dim"),
            rx.el.span("Ln 1, Col 1", class_name="dim"),
            class_name="statusbar sans",
        ),
        rx.cond(HybridState.palette_open, _palette()),
        switcher(look),
        class_name="page hybrid",
    )


def hybrid_page() -> rx.Component:
    return chrome(*[cell_view(cell) for cell in CELLS], look="hybrid")
